Here's a complete, self-contained Account Settings screen for React Native (TypeScript), built to match both iOS HIG and Material 3 conventions — 48px+ touch targets, platform-native confirmation dialog for the destructive action, dark-mode elevation tokens, and Dynamic Type–friendly text.

```tsx
import React, { useCallback, useMemo, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  View,
  useColorScheme,
} from 'react-native';
// Core RN SafeAreaView is iOS-only; swap for react-native-safe-area-context
// if it's already in your dependency tree (most RN apps that use react-navigation have it).
import { SafeAreaView } from 'react-native';

type SettingsRowType = 'navigation' | 'toggle' | 'value';

interface SettingsItem {
  id: string;
  label: string;
  type: SettingsRowType;
  value?: string;
  switchValue?: boolean;
  onToggle?: (next: boolean) => void;
  onPress?: () => void;
  disabled?: boolean;
}

interface SettingsSectionData {
  id: string;
  title?: string;
  items: SettingsItem[];
}

interface UserProfile {
  name: string;
  email: string;
  avatarUri?: string;
}

interface AccountSettingsScreenProps {
  user: UserProfile;
  sections: SettingsSectionData[];
  onEditProfile?: () => void;
  onDeleteAccount: () => Promise<void>;
}

const lightTokens = {
  bgApp: '#F2F2F7',
  bgSurface: '#FFFFFF',
  borderSubtle: '#E5E5EA',
  textPrimary: '#1C1C1E',
  textMuted: '#8E8E93',
  dangerText: '#D70015',
  accent: '#007AFF',
};

const darkTokens = {
  bgApp: '#0B0B0D',
  bgSurface: '#1C1C1E',
  borderSubtle: '#3A3A3C',
  textPrimary: '#FFFFFF',
  textMuted: '#9B9BA1',
  dangerText: '#FF453A',
  accent: '#0A84FF',
};

type Tokens = typeof lightTokens;

function useTokens(): Tokens {
  const scheme = useColorScheme();
  return useMemo(() => (scheme === 'dark' ? darkTokens : lightTokens), [scheme]);
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
}

function ProfileRow({
  user,
  tokens,
  onPress,
}: {
  user: UserProfile;
  tokens: Tokens;
  onPress?: () => void;
}) {
  const initials = useMemo(() => getInitials(user.name), [user.name]);

  return (
    <Pressable
      onPress={onPress}
      disabled={!onPress}
      accessibilityRole="button"
      accessibilityLabel={`${user.name}, ${user.email}. Edit profile`}
      android_ripple={{ color: tokens.borderSubtle }}
      hitSlop={8}
      style={({ pressed }) => [
        styles.profileRow,
        { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        pressed && Platform.OS === 'ios' && onPress ? { opacity: 0.6 } : null,
      ]}
    >
      {user.avatarUri ? (
        <Image source={{ uri: user.avatarUri }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatarFallback, { backgroundColor: tokens.accent }]}>
          <Text style={styles.avatarInitials}>{initials}</Text>
        </View>
      )}

      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: tokens.textPrimary }]} numberOfLines={1}>
          {user.name}
        </Text>
        <Text style={[styles.profileEmail, { color: tokens.textMuted }]} numberOfLines={1}>
          {user.email}
        </Text>
      </View>

      {onPress ? <Text style={[styles.chevron, { color: tokens.textMuted }]}>›</Text> : null}
    </Pressable>
  );
}

function SettingsRow({
  item,
  isLast,
  tokens,
}: {
  item: SettingsItem;
  isLast: boolean;
  tokens: Tokens;
}) {
  const isToggle = item.type === 'toggle';
  const handlePress = isToggle ? () => item.onToggle?.(!item.switchValue) : item.onPress;

  return (
    <Pressable
      onPress={handlePress}
      disabled={item.disabled || !handlePress}
      accessibilityRole={isToggle ? 'switch' : 'button'}
      accessibilityLabel={item.label}
      accessibilityState={
        isToggle
          ? { checked: !!item.switchValue, disabled: item.disabled }
          : { disabled: item.disabled }
      }
      android_ripple={{ color: tokens.borderSubtle }}
      hitSlop={8}
      style={({ pressed }) => [
        pressed && Platform.OS === 'ios' && handlePress ? { opacity: 0.6 } : null,
      ]}
    >
      <View
        style={[
          styles.row,
          !isLast && {
            borderBottomWidth: StyleSheet.hairlineWidth,
            borderBottomColor: tokens.borderSubtle,
          },
        ]}
      >
        <Text
          style={[styles.rowLabel, { color: tokens.textPrimary }]}
          numberOfLines={2}
        >
          {item.label}
        </Text>

        {isToggle ? (
          <Switch
            value={item.switchValue}
            onValueChange={item.onToggle}
            disabled={item.disabled}
            pointerEvents="none"
          />
        ) : item.type === 'value' ? (
          <View style={styles.rowRight}>
            {item.value ? (
              <Text style={[styles.rowValue, { color: tokens.textMuted }]} numberOfLines={1}>
                {item.value}
              </Text>
            ) : null}
            <Text style={[styles.chevron, { color: tokens.textMuted }]}>›</Text>
          </View>
        ) : (
          <Text style={[styles.chevron, { color: tokens.textMuted }]}>›</Text>
        )}
      </View>
    </Pressable>
  );
}

export default function AccountSettingsScreen({
  user,
  sections,
  onEditProfile,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const tokens = useTokens();
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (error) {
      Alert.alert('Something went wrong', "We couldn't delete your account. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const handleDeleteAccountPress = useCallback(() => {
    Alert.alert(
      'Delete account?',
      'This permanently deletes your account and all of your data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete Account',
          style: 'destructive',
          onPress: () => void confirmDelete(),
        },
      ],
      { cancelable: true },
    );
  }, [confirmDelete]);

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: tokens.bgApp }]}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        contentInsetAdjustmentBehavior="automatic"
      >
        <ProfileRow user={user} tokens={tokens} onPress={onEditProfile} />

        {sections.map((section) => (
          <View key={section.id} style={styles.section}>
            {section.title ? (
              <Text style={[styles.sectionTitle, { color: tokens.textMuted }]}>
                {section.title.toUpperCase()}
              </Text>
            ) : null}
            <View
              style={[
                styles.sectionCard,
                { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
              ]}
            >
              {section.items.map((item, index) => (
                <SettingsRow
                  key={item.id}
                  item={item}
                  isLast={index === section.items.length - 1}
                  tokens={tokens}
                />
              ))}
            </View>
          </View>
        ))}

        <View style={styles.section}>
          <View
            style={[
              styles.sectionCard,
              { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
            ]}
          >
            <Pressable
              onPress={handleDeleteAccountPress}
              disabled={isDeleting}
              accessibilityRole="button"
              accessibilityLabel="Delete account"
              accessibilityHint="Permanently deletes your account. Asks for confirmation first."
              android_ripple={{ color: tokens.borderSubtle }}
              hitSlop={8}
              style={({ pressed }) => [
                styles.deleteRow,
                pressed && Platform.OS === 'ios' ? { opacity: 0.6 } : null,
              ]}
            >
              {isDeleting ? (
                <ActivityIndicator color={tokens.dangerText} />
              ) : (
                <Text style={[styles.deleteLabel, { color: tokens.dangerText }]}>
                  Delete Account
                </Text>
              )}
            </Pressable>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
  },
  scrollContent: {
    paddingVertical: 16,
    paddingBottom: 48,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginHorizontal: 16,
    marginBottom: 24,
    paddingHorizontal: 16,
    paddingVertical: 12,
    minHeight: 64,
    borderRadius: 12,
    borderWidth: StyleSheet.hairlineWidth,
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
  },
  avatarFallback: {
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 20,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
    marginLeft: 16,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
    marginTop: 2,
  },
  section: {
    marginBottom: 24,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    letterSpacing: 0.4,
    marginHorizontal: 16,
    marginBottom: 8,
  },
  sectionCard: {
    marginHorizontal: 16,
    borderRadius: 12,
    borderWidth: StyleSheet.hairlineWidth,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    minHeight: 48,
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  rowLabel: {
    flex: 1,
    fontSize: 16,
    marginRight: 12,
  },
  rowRight: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  rowValue: {
    fontSize: 15,
    marginRight: 6,
  },
  chevron: {
    fontSize: 20,
    fontWeight: '400',
  },
  deleteRow: {
    minHeight: 48,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  deleteLabel: {
    fontSize: 16,
    fontWeight: '600',
  },
});
```

Key decisions behind the implementation:

- **Delete confirmation** uses `Alert.alert` with exactly two buttons (`Cancel` / `Delete Account`, `style: 'destructive'`) — matches both HIG ("alert for something the user must know now, few buttons") and Material 3 ("dialog has at most two actions"), rather than a multi-option action sheet, since there's only one destructive choice here.
- **Touch targets**: every row and the delete button use `minHeight: 48`, clearing iOS's 44pt floor and Android's 48dp floor at once.
- **Toggle rows**: the whole row is the tap target (`Switch` has `pointerEvents="none"`), not just the small switch — bigger hit area, same visual.
- **Dark mode** uses a lighter-is-nearer elevation ladder (`bgApp` darkest, `bgSurface` one step lighter) instead of inverted/shadowed surfaces, and avoids pure black.
- **Text**: no fixed row heights, `numberOfLines` instead of truncation where wrapping is safe, so it holds up under Dynamic Type / large Android font scales.
- **Async delete** is guarded with an `isDeleting` state (disables the row, shows a spinner, surfaces a retry-able error) since account deletion is a real network call that can fail.

